process.env.NODE_ENV = "test";
require("dotenv").config();

const { spawn } = require("child_process");
const http = require("http");
const mongoose = require("mongoose");

const PORT = 4597;      // dedicated baseline-suite port
const MOCK_PORT = 4611; // local mock AI provider
const TEST_DB_SUFFIX = `ascend_baseline_test_${Date.now()}`;

function buildTestUri() {
    const explicit = process.env.TEST_MONGO_URI;
    if (explicit) return explicit;
    const base = process.env.MONGO_URI;
    if (!base) return null;
    return base.replace(/\/([^/?]+)(\?|$)/, (m, dbName, q) => {
        if (/^(admin|local|config|production|prod)$/i.test(dbName)) {
            throw new Error(`Refusing to base tests on "${dbName}". Set TEST_MONGO_URI instead.`);
        }
        return `/${TEST_DB_SUFFIX}${q}`;
    });
}

const TEST_DB = buildTestUri();
if (!TEST_DB) {
    console.error("\nBaseline tests need MongoDB. Set TEST_MONGO_URI or MONGO_URI (DB name is swapped to a scratch DB).\n");
    process.exit(1);
}

let passed = 0;
let failed = 0;
const failures = [];

function assert(cond, name, extra) {
    if (cond) {
        passed += 1;
        console.log(`  ok - ${name}`);
    } else {
        failed += 1;
        failures.push(name + (extra ? ` (${extra})` : ""));
        console.log(`  FAIL - ${name}${extra ? ` (${extra})` : ""}`);
    }
}

// ============================================================
// PART 1 — RUBRIC + AI SERVICE UNIT TESTS
// ============================================================
async function unitTests() {
    console.log("\n-- rubric contract --");
    const rubric = require("../services/baselineRubric");

    assert(
        JSON.stringify(rubric.CATEGORY_KEYS) ===
        JSON.stringify(["body", "discipline", "learning", "productivity", "goalDrive"]),
        "five spec categories, spec order"
    );

    // Exact spec prompts + examples pinned.
    const spec = {
        body: ["Describe your current physical activity and exercise routine.", "I spend most of my day sitting and rarely exercise, but I want to get fitter."],
        discipline: ["How would you describe your consistency and ability to follow through on commitments?", "I make plans regularly but often lose motivation and leave things unfinished."],
        learning: ["How regularly do you learn, study, or work on developing your skills?", "I study when exams are close, but rarely spend time learning outside class."],
        productivity: ["What does a typical day look like, and how well do you complete the tasks you intend to do?", "I plan several tasks every day but usually finish only the easiest ones."],
        goalDrive: ["What goals are you working towards, and how consistently are you taking action on them?", "I have big ambitions but haven't established a clear plan or taken consistent action yet."]
    };
    for (const [k, [prompt, example]] of Object.entries(spec)) {
        assert(rubric.CATEGORIES[k].prompt === prompt, `${k} prompt matches spec exactly`);
        assert(rubric.CATEGORIES[k].example === example, `${k} example matches spec exactly`);
    }

    // Bands cover the whole range with low = difficulty, high = strength.
    const B = rubric.BANDS;
    assert(B[0][0] === 0 && B[B.length - 1][1] === 100, "bands span 0..100");
    let contiguous = true;
    for (let i = 1; i < B.length; i += 1) if (B[i][0] !== B[i - 1][1] + 1) contiguous = false;
    assert(contiguous, "bands are contiguous with no gaps/overlaps");

    const sys = rubric.buildSystemPrompt();
    assert(sys.includes("LOW scores = more reported difficulty") && sys.includes("HIGH scores = stronger"), "score direction documented in prompt");
    for (const k of rubric.CATEGORY_KEYS) {
        assert(sys.includes(rubric.CATEGORIES[k].prompt), `system prompt includes ${k} prompt`);
        assert(sys.includes(rubric.CATEGORIES[k].rules), `system prompt includes ${k} judging rules`);
    }
    assert(sys.includes('"assessments"'), "system prompt states the JSON contract");
    assert(sys.includes("not an objective measurement"), "system prompt disclaims objective measurement");

    console.log("\n-- AI response validation --");
    const good = { score: 64, explanation: "You report running twice a week.", confidence: "high", followUpQuestion: null };
    assert(rubric.validateCategoryResult(good).valid, "valid category result accepted");
    assert(rubric.validateCategoryResult({ ...good, score: null }).valid, "null score accepted when well-formed");
    assert(!rubric.validateCategoryResult({ ...good, score: 101 }).valid, "score 101 rejected");
    assert(!rubric.validateCategoryResult({ ...good, score: -1 }).valid, "negative score rejected");
    assert(!rubric.validateCategoryResult({ ...good, score: 72.5 }).valid, "float score rejected");
    assert(!rubric.validateCategoryResult({ ...good, score: "64" }).valid, "string score rejected");
    assert(!rubric.validateCategoryResult({ ...good, explanation: "" }).valid, "empty explanation rejected");
    assert(!rubric.validateCategoryResult({ ...good, confidence: "certain" }).valid, "unknown confidence rejected");
    assert(!rubric.validateCategoryResult(null).valid, "null result rejected");
    assert(!rubric.validateCategoryResult("64").valid, "non-object result rejected");
    const capped = rubric.validateCategoryResult({ ...good, explanation: "x".repeat(rubric.MAX_EXPLANATION_CHARS + 50) });
    assert(capped.valid && capped.result.explanation.length === rubric.MAX_EXPLANATION_CHARS, "overlong explanation capped, not rejected");

    const payloads = [
        [null, false],
        [{}, false],
        [{ assessments: {} }, false],
        [{ assessments: [] }, false],
        [{ assessments: { body: {}, discipline: {}, learning: {}, productivity: {} } }, false], // goalDrive missing
        [{ assessments: { body: {}, discipline: {}, learning: {}, productivity: {}, goalDrive: {} } }, true]
    ];
    for (const [p, want] of payloads) {
        assert(rubric.isWellFormedPayload(p) === want, `payload shape ${want ? "accepted" : "rejected"}: ${JSON.stringify(p).slice(0, 60)}`);
    }

    console.log("\n-- input validation (client -> server) --");
    const ok = rubric.validateDescriptions({ body: "  I run 3x/week.  ", discipline: "", learning: "", productivity: "", goalDrive: "" });
    assert(ok.errors.length === 0 && ok.clean.body === "I run 3x/week", "valid answers trimmed, no errors");
    assert(ok.clean.learning === "", "missing keys default to empty string");
    assert(rubric.validateDescriptions({ body: "x" }).errors.some((e) => e.includes("unknown field")), "unknown field rejected");
    assert(rubric.validateDescriptions({ body: 42 }).errors.length > 0, "non-string rejected");
    assert(rubric.validateDescriptions({ body: "a".repeat(rubric.MAX_DESCRIPTION_CHARS + 1) }).errors.length > 0, "overlong answer rejected");
    assert(rubric.validateDescriptions(null).errors.length > 0, "missing body object rejected");

    assert(!rubric.isAnswered(""), "empty answer not answered");
    assert(!rubric.isAnswered("   "), "whitespace answer not answered");
    assert(rubric.isAnswered("hi"), "real answer answered");
    const insuff = rubric.insufficientResult("body");
    assert(insuff.score === null, "insufficient result has NO score");
    assert(insuff.explanation === "Not enough information yet.", "insufficient result shows the spec wording");

    console.log("\n-- AI service (injected provider) --");
    const ai = require("../services/baselineAI");

    const answers = {
        body: "I sit all day and rarely move.",
        discipline: "I start plans but quit after a week.",
        learning: "",
        productivity: "I finish maybe half my tasks.",
        goalDrive: "I want a promotion but no plan yet."
    };

    // helper: OpenAI-shaped responses
    const aiPayload = (over = {}) => ({
        assessments: {
            body: { score: 30, explanation: "reports little activity", confidence: "medium", followUpQuestion: null },
            discipline: { score: 25, explanation: "reports quitting plans", confidence: "medium", followUpQuestion: null },
            learning: { score: null, explanation: "Not enough information yet.", confidence: "low", followUpQuestion: "How often do you study?" },
            productivity: { score: 45, explanation: "finishes about half", confidence: "medium", followUpQuestion: null },
            goalDrive: { score: 35, explanation: "goal without a plan", confidence: "medium", followUpQuestion: null },
            ...over
        }
    });
    const mkFetch = (impl) => {
        const calls = [];
        const f = async (url, opts) => {
            calls.push({ url, opts });
            return impl(calls.length, opts);
        };
        f.calls = calls;
        return f;
    };
    const jsonRes = (content, status = 200) => ({
        ok: status >= 200 && status < 300,
        status,
        text: async () => JSON.stringify(content),
        json: async () => content
    });
    const openaiRes = (payload) => jsonRes({ choices: [{ message: { content: JSON.stringify(payload) } }] });
    const cfg = { key: "test-key", base: "http://mock.local/v1", model: "mock-model", timeoutMs: 2000 };

    // 1. success
    let f = mkFetch(() => Promise.resolve(openaiRes(aiPayload())));
    let out = await ai.assessDescriptions(answers, { fetchImpl: f, config: cfg });
    assert(out.aiCalled === true && out.provider === "z.ai" && out.model === "mock-model", "success reports provenance");
    assert(f.calls.length === 1, "one provider call for all five categories");
    assert(out.assessments.body.score === 30 && out.assessments.goalDrive.score === 35, "validated scores returned per category");
    assert(out.assessments.learning.score === null, "null-score category stays null");
    assert(out.assessments.productivity.insufficient !== true, "answered category not marked insufficient");
    const sentBody = JSON.parse(f.calls[0].opts.body);
    assert(sentBody.temperature === 0, "deterministic temperature");
    assert(f.calls[0].opts.headers.Authorization === "Bearer test-key", "key sent only to provider");
    const sysMsg = sentBody.messages.find((m) => m.role === "system").content;
    const usrMsg = sentBody.messages.find((m) => m.role === "user").content;
    assert(sysMsg.includes("rubric v" + rubric.RUBRIC_VERSION), "system prompt carries rubric version");
    assert(!usrMsg.includes("I sit all day") === false && usrMsg.includes("goalDrive"), "user message contains answered descriptions");
    assert(usrMsg.includes("(no answer provided)"), "empty category omitted from provider payload (no empty data sent)");
    assert(!usrMsg.includes("learning:"), "empty category label line replaced, not sent as empty quote");

    // 2. all empty -> no provider call, no config needed
    f = mkFetch(() => Promise.resolve(openaiRes(aiPayload())));
    out = await ai.assessDescriptions({ body: "", discipline: "", learning: "", productivity: "", goalDrive: "" }, { fetchImpl: f, config: cfg });
    assert(f.calls.length === 0 && out.aiCalled === false, "all-empty answers never call the provider");
    assert(rubric.CATEGORY_KEYS.every((k) => out.assessments[k].score === null), "all-empty answers are all unassessed, never defaulted");

    // 3. malformed single category -> only that category invalidated
    f = mkFetch(() => Promise.resolve(openaiRes(aiPayload({ body: { score: 150, explanation: "bad", confidence: "high", followUpQuestion: null } }))));
    out = await ai.assessDescriptions(answers, { fetchImpl: f, config: cfg });
    assert(out.assessments.body.score === null, "out-of-range AI score never reaches the client");
    assert(out.assessments.discipline.score === 25, "sibling categories still valid");

    // 4. retry after transient failure
    f = mkFetch((n) => Promise.resolve(n === 1 ? jsonRes({ error: "boom" }, 500) : openaiRes(aiPayload())));
    out = await ai.assessDescriptions(answers, { fetchImpl: f, config: cfg });
    assert(out.aiCalled === true && f.calls.length === 2, "one retry after provider 500 then success");

    // 5. persistent provider failure
    f = mkFetch(() => Promise.resolve(jsonRes({ error: "boom" }, 500)));
    let threw = null;
    try { await ai.assessDescriptions(answers, { fetchImpl: f, config: cfg }); } catch (e) { threw = e; }
    assert(threw && threw.code === "AI_UNAVAILABLE" && threw.status === 502, "persistent 500 -> AI_UNAVAILABLE (502) after retry");
    assert(f.calls.length === 2, "failure retried exactly once");

    // 6. timeout
    const timeoutErr = () => { const e = new Error("The operation was aborted"); e.name = "TimeoutError"; return e; };
    f = mkFetch(() => Promise.reject(timeoutErr()));
    threw = null;
    try { await ai.assessDescriptions(answers, { fetchImpl: f, config: cfg }); } catch (e) { threw = e; }
    assert(threw && threw.code === "AI_UNAVAILABLE", "timeout -> AI_UNAVAILABLE after retry");

    // 7. malformed JSON content (twice)
    f = mkFetch(() => Promise.resolve(jsonRes({ choices: [{ message: { content: "not json {" } }] })));
    threw = null;
    try { await ai.assessDescriptions(answers, { fetchImpl: f, config: cfg }); } catch (e) { threw = e; }
    assert(threw && threw.code === "AI_INVALID_RESPONSE" && threw.status === 502, "malformed provider payload -> AI_INVALID_RESPONSE (502)");

    // 8. missing provider configuration (env cleared + restored)
    const savedKey = process.env.ZAI_API_KEY;
    const savedBase = process.env.ZAI_API_BASE;
    delete process.env.ZAI_API_KEY;
    delete process.env.ZAI_API_BASE;
    threw = null;
    try {
        await ai.assessDescriptions(answers, { fetchImpl: mkFetch(() => Promise.resolve(openaiRes(aiPayload()))) });
    } catch (e) { threw = e; } finally {
        if (savedKey !== undefined) process.env.ZAI_API_KEY = savedKey;
        if (savedBase !== undefined) process.env.ZAI_API_BASE = savedBase;
    }
    assert(threw && threw.code === "AI_NOT_CONFIGURED" && threw.status === 503, "missing config -> AI_NOT_CONFIGURED (503), no invented scores");
}

