function req(method, path, { body, cookies } = {}) {
    return new Promise((resolve, reject) => {
        const data = body ? JSON.stringify(body) : null;
        const options = { host: "localhost", port: PORT, path, method, headers: {} };
        if (data) {
            options.headers["Content-Type"] = "application/json";
            options.headers["Content-Length"] = Buffer.byteLength(data);
        }
        if (cookies) options.headers.Cookie = cookies;
        const r = http.request(options, (res) => {
            let raw = "";
            res.on("data", (c) => { raw += c; });
            res.on("end", () => {
                let json = null;
                try { json = JSON.parse(raw); } catch { /* non-JSON */ }
                resolve({ status: res.statusCode, json, raw, headers: res.headers });
            });
        });
        r.on("error", reject);
        if (data) r.write(data);
        r.end();
    });
}

function getCookie(res, name) {
    const set = res.headers["set-cookie"];
    if (!set) return null;
    for (const c of set) {
        if (c.startsWith(`${name}=`)) return c.split(";")[0];
    }
    return null;
}

async function waitUntilReady(tries = 40) {
    for (let i = 0; i < tries; i += 1) {
        try {
            await new Promise((r) => setTimeout(r, 500));
            const res = await req("GET", "/api/health");
            if (res.status === 200) return true;
        } catch { /* not up yet */ }
    }
    return false;
}

async function register(suffix) {
    const email = `bl${Date.now()}_${Math.floor(Math.random() * 1e6)}_${suffix}@test.local`;
    const res = await req("POST", "/api/auth/register", {
        body: { name: "Baseline Tester", email, password: "password123" }
    });
    return { cookies: getCookie(res, "token"), email };
}

