+// ------------------------------------------------------------
+// Baseline UI helpers (AI-estimated starting baseline).
+// Pure functions only — unit-tested in baseline.test.mjs.
+// Limits mirror server/services/baselineRubric.js so the client and
+// server agree on what a valid answer / assessment looks like.
+// ------------------------------------------------------------
+
+export const BASELINE_CATEGORY_KEYS = ["body", "discipline", "learning", "productivity", "goalDrive"];
+
+export const MAX_ANSWER_CHARS = 600;
+
+export const emptyAnswers = () => ({
+    body: "",
+    discipline: "",
+    learning: "",
+    productivity: "",
+    goalDrive: ""
+});
+
+/**
+ * Merge server-saved answers over local drafts. Only known string keys,
+ * trimmed and capped — a malformed server/API payload can never inject
+ * fields or blow past the server's length limit. Local edits are kept
+ * when the saved value is empty.
+ */
+export function mergeAnswers(local, incoming) {
+    const out = emptyAnswers();
+    for (const key of BASELINE_CATEGORY_KEYS) {
+        const localV = typeof local?.[key] === "string" ? local[key] : "";
+        const savedV = typeof incoming?.[key] === "string" ? incoming[key] : "";
+        const v = savedV.trim() ? savedV : localV;
+        out[key] = v.slice(0, MAX_ANSWER_CHARS);
+    }
+    return out;
+}
+
+/**
+ * The validated score for a category, or null when unassessed.
+ * Never coerces: strings, floats out of range, or missing entries
+ * are all "no score" so the UI can't render a fabricated percentage.
+ */
+export function scoreOf(assessments, key) {
+    const a = assessments && typeof assessments === "object" ? assessments[key] : null;
+    if (!a || typeof a !== "object") return null;
+    const s = a.score;
+    if (typeof s !== "number" || !Number.isInteger(s) || s < 0 || s > 100) return null;
+    return s;
+}
+
+/** true when the baseline has at least one result to review. */
+export function hasResults(baseline) {
+    if (!baseline || !baseline.assessments || typeof baseline.assessments !== "object") return false;
+    return BASELINE_CATEGORY_KEYS.some((k) => scoreOf(baseline.assessments, k) !== null);
+}
+
+/**
+ * Whether Continue on the description step is allowed: results exist, or
+ * the assessment attempt failed (graceful skip — unassessed categories
+ * stay explicitly unassessed).
+ */
+export function canContinueToReview(baseline, assessError) {
+    return Boolean(baseline) || Boolean(assessError);
+}
