+// Client-side unit tests for baseline UI helpers (no runner needed —
+// mirrors the server test harness style). Run: node src/utils/baseline.test.mjs
+import {
+    BASELINE_CATEGORY_KEYS,
+    MAX_ANSWER_CHARS,
+    emptyAnswers,
+    mergeAnswers,
+    scoreOf,
+    hasResults,
+    canContinueToReview
+} from "./baseline.js";
+
+let passed = 0;
+let failed = 0;
+const failures = [];
+
+function assert(cond, name, extra) {
+    if (cond) { passed += 1; console.log(`  ok - ${name}`); }
+    else { failed += 1; failures.push(name + (extra ? ` (${extra})` : "")); console.log(`  FAIL - ${name}${extra ? ` (${extra})` : ""}`); }
+}
+
+// ---- category keys match the spec order ----
+assert(
+    JSON.stringify(BASELINE_CATEGORY_KEYS) ===
+    JSON.stringify(["body", "discipline", "learning", "productivity", "goalDrive"]),
+    "five spec categories in order"
+);
+
+// ---- emptyAnswers ----
+const empty = emptyAnswers();
+assert(Object.keys(empty).length === 5 && Object.values(empty).every((v) => v === ""), "emptyAnswers has five empty strings");
+
+// ---- mergeAnswers: restore-on-revisit ----
+const saved = { body: "I run 3x/week", discipline: "", learning: "read daily", productivity: "ok", goalDrive: "ship app" };
+const merged = mergeAnswers(empty, saved);
+assert(merged.body === "I run 3x/week", "saved answer restored");
+assert(merged.discipline === "", "empty saved answer stays empty");
+
+// local edits win only when server value is empty (server trumps non-empty)
+const localEdited = { ...empty, discipline: "my local draft" };
+const merged2 = mergeAnswers(localEdited, saved);
+assert(merged2.discipline === "my local draft", "local draft preserved when saved value is empty");
+
+// ---- mergeAnswers: hostile/malformed payloads ----
+const injected = { body: "x", evil: "injected", __proto__: { polluted: true }, discipline: 42, learning: null };
+const merged3 = mergeAnswers(empty, injected);
+assert(!("evil" in merged3), "unknown fields dropped");
+assert(merged3.discipline === "", "non-string saved value ignored");
+assert(merged3.learning === "", "null saved value ignored");
+assert(!({}.polluted), "prototype pollution not introduced");
+const long = "a".repeat(MAX_ANSWER_CHARS + 50);
+const merged4 = mergeAnswers(empty, { body: long });
+assert(merged4.body.length === MAX_ANSWER_CHARS, "answers capped at MAX_ANSWER_CHARS");
+
+// ---- scoreOf: only validated integers pass ----
+assert(scoreOf({ body: { score: 72 } }, "body") === 72, "valid integer score returned");
+assert(scoreOf({ body: { score: 0 } }, "body") === 0, "zero score is a real score");
+assert(scoreOf({ body: { score: 100 } }, "body") === 100, "100 score accepted");
+assert(scoreOf({ body: { score: null } }, "body") === null, "null score is unassessed");
+assert(scoreOf({ body: { score: 72.5 } }, "body") === null, "float score rejected (no fabricated rounding)");
+assert(scoreOf({ body: { score: "72" } }, "body") === null, "string score rejected");
+assert(scoreOf({ body: { score: 101 } }, "body") === null, "out-of-range high score rejected");
+assert(scoreOf({ body: { score: -1 } }, "body") === null, "negative score rejected");
+assert(scoreOf({}, "body") === null, "missing category is unassessed");
+assert(scoreOf(null, "body") === null, "null assessments is unassessed");
+assert(scoreOf({ body: "72" }, "body") === null, "malformed entry is unassessed");
+
+// ---- hasResults ----
+assert(!hasResults(null), "no baseline -> no results");
+assert(!hasResults({ assessments: { body: { score: null } } }), "all-null assessments -> no results");
+assert(hasResults({ assessments: { body: { score: null }, discipline: { score: 40 } } }), "one score counts as results");
+
+// ---- canContinueToReview: skip allowed only after an attempt failed ----
+assert(!canContinueToReview(null, ""), "cannot continue with nothing");
+assert(canContinueToReview({ assessments: {} }, ""), "can continue with results");
+assert(canContinueToReview(null, "AI unavailable"), "can continue after a failed attempt (category stays unassessed)");
+assert(!canContinueToReview(null, ""), "empty error does not unlock continue");
+
+// ---- summary ----
+console.log(`\n${passed} passed, ${failed} failed`);
+if (failed > 0) {
+    console.log("Failures:\n - " + failures.join("\n - "));
+    process.exit(1);
+}
