// ------------------------------------------------------------
// AI BASELINE (onboarding) — unit + API test suite.
// Standalone: node test/baseline.test.js  (same harness style as gym.test.js)
//
// Part 1 (unit, in-process): rubric contract, AI response validation,
//   provider failures/timeouts/retries, missing provider configuration.
// Part 2 (integration): spawns server.js against a scratch DB with a local
//   MOCK OpenAI-compatible provider (no external network, no real key):
//   401s, validation, persistence, reassessment, duplicate prevention,
//   confirmed-baseline preservation, provider failure mapping, ownership,
//   onboarding completion, export coverage.
// ------------------------------------------------------------
process.env.NODE_ENV = "test";
require("dotenv").config();

const { spawn } = require("child_process");
const http = require("http");
const mongoose = require("mongoose");

const PORT = 4597;      // dedicated baseline-suite port
const MOCK_PORT = 4611; // local mock AI provider
const TEST_DB_SUFFIX = `ascend_baseline_test_${Date.now()}`;

function buildTestUri() {
    const explicit = process.env.TEST_MONGO_URI;
    if (explicit) return explicit;
    const base = process.env.MONGO_URI;
    if (!base) return null;
    return base.replace(/\/([^/?]+)(\?|$)/, (m, dbName, q) => {
        if (/^(admin|local|config|production|prod)$/i.test(dbName)) {
            throw new Error(`Refusing to base tests on "${dbName}". Set TEST_MONGO_URI instead.`);
        }
        return `/${TEST_DB_SUFFIX}${q}`;
    });
}

const TEST_DB = buildTestUri();
if (!TEST_DB) {
    console.error("\nBaseline tests need MongoDB. Set TEST_MONGO_URI or MONGO_URI (DB name is swapped to a scratch DB).\n");
    process.exit(1);
}

let passed = 0;
let failed = 0;
const failures = [];

function assert(cond, name, extra) {
    if (cond) {
        passed += 1;
        console.log(`  ok - ${name}`);
    } else {
        failed += 1;
        failures.push(name + (extra ? ` (${extra})` : ""));
        console.log(`  FAIL - ${name}${extra ? ` (${extra})` : ""}`);
    }
}

