// ============================================================
// BASELINE AI SERVICE — provider adapter for the onboarding baseline.
//
// Provider: Z.ai (OpenAI-compatible chat completions over plain fetch —
// no SDK dependency). Configured entirely from the server environment:
//   ZAI_API_KEY   (required) — secret; backend only, never sent to clients
//   ZAI_API_BASE  (required) — OpenAI-compatible base URL, e.g. https://…/v1
//   ZAI_MODEL     (optional) — defaults to "glm-4-flash"
//   AI_TIMEOUT_MS (optional) — per-request timeout, defaults to 20000
//
// None of these are read from client code; if they are missing the route
// returns 503 AI_NOT_CONFIGURED instead of inventing scores.
//
// Behaviour contract:
//   - ONE provider call scores all five categories (minimal personal data
//     sent: only the user's short answers, nothing else).
//   - Empty answers are filtered out locally and never sent.
//   - Network errors / timeouts / 5xx / 429 → one retry, then AI_UNAVAILABLE.
//   - Unparseable or malformed top-level payload → one retry, then
//     AI_INVALID_RESPONSE.
//   - A malformed single category never becomes a score: that category
//     comes back unassessed (score null) via the rubric validator.
// ============================================================

const {
    CATEGORY_KEYS,
    CATEGORIES,
    buildSystemPrompt,
    JSON_CONTRACT,
    isAnswered,
    insufficientResult,
    invalidResult,
    validateCategoryResult,
    isWellFormedPayload
} = require("./baselineRubric");

class AIConfigError extends Error {
    constructor(message) {
        super(message);
        this.name = "AIConfigError";
        this.code = "AI_NOT_CONFIGURED";
        this.status = 503;
    }
}

class AIUnavailableError extends Error {
    constructor(message) {
        super(message);
        this.name = "AIUnavailableError";
        this.code = "AI_UNAVAILABLE";
        this.status = 502;
    }
}

class AIInvalidResponseError extends Error {
    constructor(message) {
        super(message);
        this.name = "AIInvalidResponseError";
        this.code = "AI_INVALID_RESPONSE";
        this.status = 502;
    }
}

function getConfig() {
    const key = String(process.env.ZAI_API_KEY || "").trim();
    const base = String(process.env.ZAI_API_BASE || "").trim().replace(/\/+$/, "");
    if (!key || !base) {
        throw new AIConfigError(
            "AI baseline assessment is not configured on this server (set ZAI_API_KEY and ZAI_API_BASE)."
        );
    }
    const model = String(process.env.ZAI_MODEL || "glm-4-flash").trim();
    const timeoutRaw = Number(process.env.AI_TIMEOUT_MS);
    const timeoutMs = Number.isFinite(timeoutRaw) && timeoutRaw >= 100 ? timeoutRaw : 20000;
    return { key, base, model, timeoutMs };
}

function buildUserMessage(descriptions) {
    const lines = ["Score the following self-descriptions:"];
    for (const key of CATEGORY_KEYS) {
        const text = descriptions[key];
        lines.push("", `${CATEGORIES[key].label} (${key}):`, isAnswered(text) ? `"${text}"` : "(no answer provided)");
    }
    return lines.join("\n");
}

/** Strip accidental ``` fences before parsing. */
function parseModelJson(content) {
    if (typeof content !== "string") return null;
    const stripped = content.trim().replace(/^```(?:json)?\s*/i, "").replace(/\s*```$/, "");
    try {
        return JSON.parse(stripped);
    } catch {
        return null;
    }
}

async function callProvider({ key, base, model, timeoutMs }, system, user, fetchImpl) {
    let res;
    try {
        res = await fetchImpl(`${base}/chat/completions`, {
            method: "POST",
            headers: {
                "Content-Type": "application/json",
                Authorization: `Bearer ${key}`
            },
            body: JSON.stringify({
                model,
                temperature: 0,
                response_format: { type: "json_object" },
                messages: [
                    { role: "system", content: system },
                    { role: "user", content: user }
                ]
            }),
            signal: AbortSignal.timeout(timeoutMs)
        });
    } catch (e) {
        const reason = e && (e.name === "TimeoutError" || e.name === "AbortError")
            ? "timed out"
            : `network error (${e.message})`;
        throw new AIUnavailableError(`AI provider request ${reason}`);
    }

    if (!res.ok) {
        let detail = "";
        try { detail = (await res.text()).slice(0, 200); } catch { /* body unreadable */ }
        throw new AIUnavailableError(`AI provider returned HTTP ${res.status}${detail ? `: ${detail}` : ""}`);
    }

    let data;
    try { data = await res.json(); } catch { throw new AIInvalidResponseError("AI provider returned non-JSON body"); }

    const content = data && data.choices && data.choices[0] && data.choices[0].message
        ? data.choices[0].message.content
        : null;
    const parsed = parseModelJson(content);
    if (!isWellFormedPayload(parsed)) {
        throw new AIInvalidResponseError("AI provider returned a malformed assessment payload");
    }
    return parsed;
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

/**
 * Assess the five descriptions.
 *
 * @param {object} descriptions - { body, discipline, learning, productivity, goalDrive }
 * @param {object} [opts]
 * @param {Function} [opts.fetchImpl] - injectable fetch (tests)
 * @param {object}  [opts.config]     - injectable config (tests)
 * @returns {Promise<{assessments, model, provider, aiCalled}>}
 * @throws AIConfigError | AIUnavailableError | AIInvalidResponseError
 */
async function assessDescriptions(descriptions, opts = {}) {
    const fetchImpl = opts.fetchImpl || fetch;

    // Categories with no answer never leave the server and never get a number.
    const assessments = {};
    const answeredKeys = [];
    for (const key of CATEGORY_KEYS) {
        if (isAnswered(descriptions[key])) answeredKeys.push(key);
        else assessments[key] = insufficientResult(key);
    }

    if (!answeredKeys.length) {
        return { assessments, model: null, provider: null, aiCalled: false };
    }

    const config = opts.config || getConfig(); // throws AIConfigError when unset
    const system = buildSystemPrompt();
    const user = buildUserMessage(descriptions);

    // Attempt 1, one retry on transient or malformed responses.
    let parsed;
    try {
        parsed = await callProvider(config, system, user, fetchImpl);
    } catch (firstError) {
        if (firstError instanceof AIConfigError) throw firstError;
        const retryable = firstError instanceof AIUnavailableError || firstError instanceof AIInvalidResponseError;
        if (!retryable) throw new AIUnavailableError(`AI provider request failed (${firstError.message})`);
        await sleep(250);
        try {
            parsed = await callProvider(config, system, user, fetchImpl);
        } catch (secondError) {
            if (secondError instanceof AIInvalidResponseError) throw secondError;
            throw secondError instanceof AIUnavailableError
                ? secondError
                : new AIUnavailableError(`AI provider request failed (${secondError.message})`);
        }
    }

    // Per-category validation: a malformed category becomes unassessed,
    // never a guessed score.
    for (const key of CATEGORY_KEYS) {
        if (!answeredKeys.includes(key)) continue; // already unassessed locally
        const { valid, result } = validateCategoryResult(parsed.assessments[key]);
        assessments[key] = valid ? result : invalidResult();
    }

    return {
        assessments,
        model: config.model,
        provider: "z.ai",
        aiCalled: true
    };
}

module.exports = {
    assessDescriptions,
    getConfig,
    buildUserMessage,
    AIConfigError,
    AIUnavailableError,
    AIInvalidResponseError
};
