const mongoose = require("mongoose");

// ============================================================
// BASELINE — the AI-estimated onboarding starting point.
//
// Exactly ONE document per user (unique userId), created on first assess
// and only replaced as a whole through an explicit confirm (reassessment)
// or the account reset/delete flows. It is deliberately stored apart from
// activity-based metrics: these scores come from self-descriptions via an
// AI rubric (see services/baselineRubric.js), NOT from tracked habits,
// tasks, goals or workouts, and must never be blended with them silently.
//
// `status`:
//   draft     — generated, awaiting user review/confirm
//   confirmed — user pressed "Start ascending"; preserved verbatim
//               if onboarding is revisited (never silently replaced)
// ============================================================

const VALID_STATUSES = ["draft", "confirmed"];
const CONF = { minimize: true };

const assessmentSchema = new mongoose.Schema(
    {
        // null = genuinely unassessed (empty/vague answer, malformed AI reply,
        // or provider failure). Never substituted with a default number.
        score: { type: Number, default: null, min: 0, max: 100 },

        // Grounded one/two-sentence justification for the score.
        explanation: { type: String, default: "", maxlength: 500 },

        // "high" | "medium" | "low" — provider's stated confidence.
        confidence: { type: String, default: null, enum: ["high", "medium", "low", null] },

        // Optional short clarifying question when information was missing.
        followUpQuestion: { type: String, default: null, maxlength: 300 },

        // true when there was not enough relevant information to score.
        // Displayed as "Not enough information yet" — no fabricated number.
        insufficient: { type: Boolean, default: false }
    },
    { _id: false }
);

const baselineSchema = new mongoose.Schema(
    {
        userId: {
            type: mongoose.Schema.Types.ObjectId,
            ref: "User",
            required: true,
            unique: true
        },

        // The user's five self-descriptions (trimmed, length-capped server-side).
        answers: {
            body: { type: String, default: "", maxlength: 600 },
            discipline: { type: String, default: "", maxlength: 600 },
            learning: { type: String, default: "", maxlength: 600 },
            productivity: { type: String, default: "", maxlength: 600 },
            goalDrive: { type: String, default: "", maxlength: 600 }
        },

        // AI-generated assessments, keyed by category. Draft = last assess
        // call's output; confirmed = the locked-in starting baseline.
        assessments: {
            type: Map,
            of: assessmentSchema,
            default: () => ({})
        },

        status: { type: String, enum: VALID_STATUSES, default: "draft" },

        // Which scores belong to `assessments` (the confirmed baseline).
        confirmedAt: { type: Date, default: null },
        assessedAt: { type: Date, default: null },

        // Provenance: rubric + model actually used (for auditability and to
        // keep future re-assessments distinguishable from the original).
        rubricVersion: { type: String, default: "" },
        model: { type: String, default: "" }
    },
    { timestamps: true, minimize: false }
);

baselineSchema.index({ userId: 1 });

module.exports = mongoose.model("Baseline", baselineSchema);
